import argparse
import sys

def main():
    parser = argparse.ArgumentParser(description="Build a stdin histogram CLI.")
    parser.add_argument('--min', type=int, default=0, help="Drop values below the supplied integer.")
    args = parser.parse_args()

    histogram = {}

    for line in sys.stdin:
        for value in line.split():
            try:
                num = int(value)
                if num >= args.min:
                    histogram[num] = histogram.get(num, 0) + 1
            except ValueError:
                print(f"Invalid input: {value}", file=sys.stderr)

    for key in sorted(histogram.keys()):
        print(f"{key} {histogram[key]}")

if __name__ == "__main__":
    main()

import argparse
import json
import os
import sys

def load_bookmarks(file_path):
    if os.path.exists(file_path):
        with open(file_path, 'r') as file:
            return json.load(file)
    return {}

def save_bookmarks(file_path, bookmarks):
    with open(file_path, 'w') as file:
        json.dump(bookmarks, file, indent=4)

def add_bookmark(bookmarks, name, url):
    bookmarks[name] = url

def list_bookmarks(bookmarks):
    for name, url in sorted(bookmarks.items()):
        print(f"{name}\t{url}")

def remove_bookmark(bookmarks, name):
    if name in bookmarks:
        del bookmarks[name]
    else:
        sys.exit(1)

def main():
    parser = argparse.ArgumentParser(description="Persistent command-line bookmark manager.")
    parser.add_argument("file_path", help="Path to the JSON data file.")
    parser.add_argument("action", choices=["add", "list", "remove"], help="Action to perform.")
    parser.add_argument("name", nargs='?', help="Name of the bookmark (required for add and remove).")
    parser.add_argument("url", nargs='?', help="URL of the bookmark (required for add).")
    args = parser.parse_args()

    bookmarks = load_bookmarks(args.file_path)

    if args.action == "add":
        if args.name and args.url:
            add_bookmark(bookmarks, args.name, args.url)
        else:
            print("Error: Both name and URL are required for the 'add' action.")
            sys.exit(1)
    elif args.action == "list":
        list_bookmarks(bookmarks)
    elif args.action == "remove":
        if args.name:
            remove_bookmark(bookmarks, args.name)
        else:
            print("Error: Name is required for the 'remove' action.")
            sys.exit(1)

    save_bookmarks(args.file_path, bookmarks)

if __name__ == "__main__":
    main()

import sys
import json
from decimal import Decimal, getcontext

def summarize_expenses(category=None):
    getcontext().prec = 2  # Set precision for Decimal operations
    expenses = {}

    for line in sys.stdin:
        parts = line.strip().split(',')
        if len(parts) != 2:
            continue
        category_name, amount_str = parts
        if category and category_name != category:
            continue
        try:
            amount = Decimal(amount_str)
        except ValueError:
            continue
        if category_name not in expenses:
            expenses[category_name] = Decimal(0)
        expenses[category_name] += amount

    return {category_name: str(amount) for category_name, amount in expenses.items()}

def main():
    import argparse
    parser = argparse.ArgumentParser(description='Summarize CSV expenses from stdin.')
    parser.add_argument('--category', type=str, help='Limit results to a specific category.')
    args = parser.parse_args()

    result = summarize_expenses(args.category)
    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()

def print_board(board):
    for row in board:
        print(" | ".join(row))
        print("-" * 5)

def check_winner(board, player):
    # Check rows, columns and diagonals for a win
    for i in range(3):
        if all(board[i][j] == player for j in range(3)) or all(board[j][i] == player for j in range(3)):
            return True
    if board[0][0] == board[1][1] == board[2][2] == player or board[0][2] == board[1][1] == board[2][0] == player:
        return True
    return False

def is_full(board):
    return all(board[i][j] != ' ' for i in range(3) for j in range(3))

def main():
    board = [[' ' for _ in range(3)] for _ in range(3)]
    current_player = 'X'

    while True:
        print_board(board)
        try:
            move = int(input(f"Player {current_player}, enter your move (1-9): "))
            if move < 1 or move > 9:
                raise ValueError("Move must be between 1 and 9.")
            row, col = (move - 1) // 3, (move - 1) % 3
            if board[row][col] != ' ':
                raise ValueError("Square already occupied.")
            board[row][col] = current_player
        except ValueError as e:
            print(e)
            continue

        if check_winner(board, current_player):
            print_board(board)
            print(f"Player {current_player} wins!")
            break
        if is_full(board):
            print_board(board)
            print("Draw!")
            break

        current_player = 'O' if current_player == 'X' else 'X'

if __name__ == "__main__":
    main()

import os
import json
import argparse

def get_directory_inventory(directory, suffix=None):
    inventory = {}

    for root, dirs, files in os.walk(directory):
        for file in files:
            if file.startswith('.') or file.endswith('.sym'):
                continue
            if suffix and not file.endswith(suffix):
                continue
            file_path = os.path.join(root, file)
            relative_path = os.path.relpath(file_path, directory)
            inventory[relative_path] = os.path.getsize(file_path)

    return inventory

def main():
    parser = argparse.ArgumentParser(description="Build a directory inventory command.")
    parser.add_argument("directory", type=str, help="The directory to inventory.")
    parser.add_argument("--suffix", type=str, help="Optional file suffix to filter by.")
    args = parser.parse_args()

    if not os.path.isdir(args.directory):
        print(f"Error: {args.directory} is not a valid directory.")
        return

    inventory = get_directory_inventory(args.directory, args.suffix)
    print(json.dumps(inventory, indent=4))

if __name__ == "__main__":
    main()

import argparse
import sys

def validate_transaction(line, line_number):
    try:
        parts = line.strip().split('\t')
        if len(parts) != 2:
            raise ValueError("Invalid format")
        transaction_id, cents = parts
        if not transaction_id or not transaction_id.strip():
            raise ValueError("Empty transaction ID")
        if not cents.isdigit():
            raise ValueError("Invalid cents value")
        return transaction_id, int(cents)
    except Exception as e:
        print(f"Error on line {line_number}: {e}", file=sys.stderr)
        sys.exit(1)

def main():
    parser = argparse.ArgumentParser(description="Validate transactions in a JSONL file.")
    parser.add_argument("file", type=argparse.FileType('r'), help="JSONL file containing transactions")
    args = parser.parse_args()

    transaction_ids = set()
    total_cents = 0

    for line_number, line in enumerate(args.file, start=1):
        if not line.strip():
            continue
        transaction_id, cents = validate_transaction(line, line_number)
        if transaction_id in transaction_ids:
            print(f"Duplicate transaction ID: {transaction_id}", file=sys.stderr)
            sys.exit(1)
        transaction_ids.add(transaction_id)
        total_cents += cents

    print(total_cents)

if __name__ == "__main__":
    main()

import json
import sys

def load_quiz(file_path):
    with open(file_path, 'r') as file:
        quiz_data = json.load(file)
    return quiz_data

def ask_question(question):
    print(question['question'])
    user_answer = input("Your answer: ").strip().lower()
    return user_answer

def check_answer(user_answer, correct_answer):
    return user_answer == correct_answer.lower()

def main():
    if len(sys.argv) != 2:
        print("Usage: python quiz.py <path_to_quiz_file.json>")
        sys.exit(1)

    quiz_file_path = sys.argv[1]
    quiz_data = load_quiz(quiz_file_path)

    score = 0
    total_questions = len(quiz_data)

    for question in quiz_data:
        user_answer = ask_question(question)
        if check_answer(user_answer, question['answer']):
            print("Correct!\n")
            score += 1
        else:
            print(f"Incorrect. The correct answer is: {question['answer']}\n")

    print(f"Quiz completed. Your score is {score}/{total_questions}")

if __name__ == "__main__":
    main()
